//! Text shown by Rust. The Mac's menus, dialogs and window titles come from the catalog's `native`
//! area (`strings_catalog.rs`, generated by `pnpm i18n:apple`) in the language the system prefers,
//! chosen as the page chooses it (`resolveLocale`). The `devot` command's output stays English, and
//! so does the name a kept-aside mirror file gets, which every device must read back the same.

use std::sync::OnceLock;

#[path = "strings_catalog.rs"]
mod catalog;

pub use catalog::Native;

pub const APP_NAME: &str = "Devot";
pub const MIRROR_EDITED_SUFFIX: &str = " (edited outside Devot)";

/// The native text in the language the system prefers, chosen once per run.
pub fn native() -> &'static Native {
    static CHOSEN: OnceLock<&'static Native> = OnceLock::new();
    CHOSEN.get_or_init(|| for_languages(&crate::native::preferred_languages()))
}

/// The first of `preferred` (BCP 47 tags, most preferred first) that has a catalog, else English;
/// Traditional Chinese passes on to the next, since only Simplified ships.
pub fn for_languages<S: AsRef<str>>(preferred: &[S]) -> &'static Native {
    preferred
        .iter()
        .find_map(|tag| catalog_for(tag.as_ref()))
        .unwrap_or(&catalog::EN)
}

fn catalog_for(tag: &str) -> Option<&'static Native> {
    let lower = tag.to_ascii_lowercase().replace('_', "-");
    let mut subtags = lower.split('-');
    match subtags.next()? {
        "en" => Some(&catalog::EN),
        "zh" if subtags.any(|s| matches!(s, "hant" | "tw" | "hk" | "mo")) => None,
        "zh" => Some(&catalog::ZH_HANS),
        _ => None,
    }
}

