#[cfg(test)]
mod tests {
    use super::*;

    fn chosen(preferred: &[&str]) -> &'static str {
        for_languages(preferred).menu_file
    }

    #[test]
    fn follows_the_first_preferred_language_with_a_catalog() {
        let chinese = catalog::ZH_HANS.menu_file;
        assert_eq!(chosen(&[]), "File");
        assert_eq!(chosen(&["en-US"]), "File");
        assert_eq!(chosen(&["zh-Hans-CN", "en"]), chinese);
        assert_eq!(chosen(&["zh-CN"]), chinese);
        assert_eq!(chosen(&["zh_SG"]), chinese);
        assert_eq!(chosen(&["zh"]), chinese);
        assert_eq!(chosen(&["fr-FR", "zh-Hans"]), chinese);
        assert_eq!(chosen(&["fr-FR", "de"]), "File");
    }

    #[test]
    fn passes_traditional_chinese_on_to_the_next_language() {
        assert_eq!(chosen(&["zh-Hant-TW", "en"]), "File");
        assert_eq!(chosen(&["zh-TW"]), "File");
        assert_eq!(chosen(&["zh-HK", "zh-Hans"]), catalog::ZH_HANS.menu_file);
        assert_eq!(chosen(&["zh-MO"]), "File");
    }

    #[test]
    fn translates_the_menus() {
        assert_ne!(catalog::ZH_HANS.menu_file, catalog::EN.menu_file);
        assert_eq!(
            catalog::ZH_HANS.startup_folder.matches("{folder}").count(),
            1
        );
        assert_eq!(
            catalog::ZH_HANS
                .plugin_export_note
                .matches("{title}")
                .count(),
            1
        );
    }
}
